    data = input().strip().split()

    # Parse the input into a 3x3 grid
    grid = [[int(data[i * 3 + j]) for j in range(3)] for i in range(3)]

    # Collect all possible sums a_i + b_j
    possible_sums = set()

    # Iterate over all possible pairs of a_i and b_j
    for a1 in range(101):
        for a2 in range(101):
            for a3 in range(101):
                for b1 in range(101):
                    for b2 in range(101):
                        for b3 in range(101):
                            possible_sums.add(a1 + b1)
                            possible_sums.add(a2 + b2)
                            possible_sums.add(a3 + b3)

    # Check if all values in the grid are in the set of possible sums
    for i in range(3):
        for j in range(3):
            if grid[i][j] not in possible_sums:
                print("No")
                return

    print("Yes")

