            return

    # Check the differences between adjacent cells in each column
    for j in range(3):
        if grid[1][j] - grid[0][j] != grid[2][j] - grid[1][j]:
            print("No")
            return

    # If all checks pass, Takahashi's statement is correct
    print("Yes")

